/* Brief 17 §1–2: Waeve Rail Fibre — leased cores in the railway duct. Cheap to light,
   limited to the Java rail corridor, and cut whenever the track crew opens the duct.
   `rail:true` carries two extra effects: coreQ (poor cores, less usable capacity) and
   cutRisk (per-link daily chance of a rail cut). Not a subsea cable; never add `rail`
   to anything in CABLES. */
const WEAVE_CABLES=[
 {id:'waeve',name:'Waeve Rail Fibre',price:0.20,age:'new',rail:true,coreQ:0.6,cutRisk:0.04,
  blurb:'Leased cores in the railway duct. You did not dig anything: the track was already there, and so was the duct. The track crew knows where your fibre is.',
  /* Java only. A railway duct cannot cross the Bali Strait, so sby-dps was removed — the map
     offered "Waeve Rail Fibre" on a subsea route, which made no sense at all. */
  pairs:[['jkt','bdg'],['jkt','smg'],['smg','jog'],['jog','sby']]},
];
/* The SEA map carries three layers of cable: the global systems that happen to land in two SEA
   cities, the regional systems this fork added (SEA_NEW_CABLES), and the Indonesian domestic
   systems. The last two are declared further down the file, so this table is built after them
   rather than next to SEA_NEW_CABLES — a `const` read before its declaration is a TDZ error
   that stops the whole script from parsing. */
const SEA_CABLES=CABLES.filter(c=>c.pairs.every(([a,b])=>SEA_IDS.has(a)&&SEA_IDS.has(b)))
 .concat(SEA_NEW_CABLES, IDN_NEW_CABLES, WEAVE_CABLES);
const IDN_CITIES=SEA_CITIES.filter(c=>SEA_IDN_LANDS.has(c.land));
const IDN_IDS=new Set(IDN_CITIES.map(c=>c.id));
